def solve(payload):
    import math
    vertices, faces = payload["vertices"], payload["faces"]
    if any(i < 0 or i >= len(vertices) for f in faces for i in f):
        return {"error": "invalid_index"}
    edges = {}
    total = 0.0
    degenerate = 0
    for face in faces:
        a, b, c = [vertices[i] for i in face]
        u = [b[i]-a[i] for i in range(3)]
        v = [c[i]-a[i] for i in range(3)]
        cross = [u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0]]
        area = math.sqrt(sum(x*x for x in cross))/2
        total += area
        if area <= 1e-12:
            degenerate += 1
            continue
        for i, j in ((face[0], face[1]), (face[1], face[2]), (face[2], face[0])):
            key = tuple(sorted((i, j)))
            edges[key] = edges.get(key, 0)+1
    return {"area_m2": total, "boundary_edges": sum(n == 1 for n in edges.values()), "nonmanifold_edges": sum(n > 2 for n in edges.values()), "degenerate_faces": degenerate}
